parameters.query:
CALL {
  CALL gds.graph.nodeProperties.stream('eth_heist_h4_v1','ppr_v1') YIELD nodeId, propertyValue AS score
  WITH nodeId, score ORDER BY score DESC LIMIT 120
  RETURN collect(gds.util.asNode(nodeId).address) AS a
}
CALL {
  CALL gds.graph.nodeProperties.stream('eth_heist_h4_amt5_v1','ppr_v1') YIELD nodeId, propertyValue AS score
  WITH nodeId, score ORDER BY score DESC LIMIT 120
  RETURN collect(gds.util.asNode(nodeId).address) AS b
}
RETURN size(a) AS nA, size(b) AS nB, size(apoc.coll.intersection(a,b)) AS overlap, apoc.coll.subtract(a,b)[0..20] AS onlyA, apoc.coll.subtract(b,a)[0..20] AS onlyB

CALL {
  CALL gds.graph.nodeProperties.stream('eth_heist_h4_amt5_v1','ppr_v1') YIELD nodeId, propertyValue AS score
  WITH nodeId, score ORDER BY score DESC LIMIT 120
  RETURN collect(gds.util.asNode(nodeId).address) AS a
}
CALL {
  CALL gds.graph.nodeProperties.stream('eth_heist_h4_v1','eig_v1') YIELD nodeId, propertyValue AS score
  WITH nodeId, score ORDER BY score DESC LIMIT 120
  RETURN collect(gds.util.asNode(nodeId).address) AS b
}
RETURN size(a) AS nA, size(b) AS nB, size(apoc.coll.intersection(a,b)) AS overlap, apoc.coll.intersection(a,b)[0..20] AS sampleOverlap, apoc.coll.subtract(a,b)[0..10] AS ppr_only, apoc.coll.subtract(b,a)[0..10] AS eig_only

CALL {
  CALL gds.graph.nodeProperties.stream('eth_heist_h4_amt5_v1','ppr_v1') YIELD nodeId, propertyValue AS score
  WITH nodeId, score ORDER BY score DESC LIMIT 100
  RETURN collect(gds.util.asNode(nodeId).address) AS a
}
CALL {
  CALL gds.graph.nodeProperties.stream('eth_heist_h4_amt5_3d','ppr_v1') YIELD nodeId, propertyValue AS score
  WITH nodeId, score ORDER BY score DESC LIMIT 100
  RETURN collect(gds.util.asNode(nodeId).address) AS b
}
RETURN size(a) AS nA, size(b) AS nB, size(apoc.coll.intersection(a,b)) AS overlap, apoc.coll.subtract(b,a)[0..20] AS only3d, apoc.coll.subtract(a,b)[0..20] AS only14d

