parameters.cypher_query:
MATCH (n:Address)-[r:TRANSFER]->(m:Address)
WHERE r.time >= datetime('2025-02-21T14:15:11Z') AND r.time <= datetime('2025-03-07T14:15:11Z')
RETURN gds.graph.project(
  $graph_name, n, m,
  {
    sourceNodeLabels: labels(n),
    targetNodeLabels: labels(m),
    relationshipType: type(r),
    relationshipProperties: {amount: toFloat(r.amount)}
  }
)

MATCH p=(s:Address {address: '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'})-[:TRANSFER*1..3]->(n:Address)
WITH DISTINCT n
MATCH (n)-[r:TRANSFER]->(m:Address)
WHERE r.time >= datetime('2025-02-21T14:15:11Z')
RETURN gds.graph.project(
  $graph_name, n, m,
  {
    sourceNodeLabels: labels(n),
    targetNodeLabels: labels(m),
    relationshipType: type(r),
    relationshipProperties: {amount: toFloat(r.amount)}
  }
)

MATCH (s:Address {address: '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'})
CALL {
  WITH s
  MATCH p=(s)-[:TRANSFER*1..3]->(n:Address)
  RETURN collect(DISTINCT n) AS ns
}
WITH ns, s
WITH ns + [s] AS ns2
UNWIND ns2 AS n
MATCH (n)-[r:TRANSFER]->(m:Address)
WHERE r.time >= datetime('2025-02-21T14:15:11Z')
RETURN gds.graph.project(
  $graph_name, n, m,
  {
    sourceNodeLabels: labels(n),
    targetNodeLabels: labels(m),
    relationshipType: type(r),
    relationshipProperties: {amount: toFloat(r.amount)}
  }
)

MATCH (s:Address {address: '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'})
CALL {
  WITH s
  MATCH p=(s)-[:TRANSFER*1..3]->(n:Address)
  RETURN collect(DISTINCT n) AS ns
}
WITH ns, s
WITH ns + [s] AS ns2
UNWIND ns2 AS n
MATCH (n)-[r:TRANSFER {asset: 'ETH'}]->(m:Address)
WHERE r.time >= datetime('2025-02-21T14:15:11Z')
RETURN gds.graph.project(
  $graph_name, n, m,
  {
    sourceNodeLabels: labels(n),
    targetNodeLabels: labels(m),
    relationshipType: type(r),
    relationshipProperties: {amount: toFloat(r.amount)}
  }
)

