parameters.cypher_query:
MATCH (victim:Address {address: '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'})
CALL {
  WITH victim
  MATCH path = (victim)-[rs:TRANSFER*1..3]->(n:Address)
  WHERE ALL(r IN rs WHERE r.asset = 'ETH' AND r.time >= datetime('2025-02-21T14:16:11Z') AND r.time <= datetime('2025-03-08T00:00:00Z') AND r.amount >= 1000.0)
  RETURN collect(DISTINCT n) AS nodes
}
UNWIND nodes AS n
OPTIONAL MATCH (n)-[r:TRANSFER]->(m:Address)
WHERE r.asset = 'ETH' AND r.time >= datetime('2025-02-21T14:16:11Z') AND r.time <= datetime('2025-03-08T00:00:00Z') AND r.amount >= 1000.0
RETURN gds.graph.project(
  $graph_name, n, m,
  {
    sourceNodeLabels: labels(n),
    targetNodeLabels: labels(m),
    relationshipType: type(r),
    relationshipProperties: {amount: toFloat(r.amount), cost: 1.0 / (toFloat(r.amount) + 1e-9)}
  }
)

