parameters.query:
CALL {
  MATCH (s:Address {address: '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'})
  CALL gds.shortestPath.dijkstra.stream('hack_eth_flow_v2', {
    sourceNode: s,
    relationshipWeightProperty: 'neglog_w1'
  })
  YIELD nodeId, cost
  RETURN nodeId, cost
}
WITH gds.util.asNode(nodeId) AS n, cost
RETURN n.address AS address, exp(-cost) AS score
ORDER BY score DESC
LIMIT 150

// Direct contributions
CALL {
  MATCH (s:Address {address: '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'})- [r1:TRANSFER]->(v:Address)
  WHERE r1.asset = 'ETH' AND toFloat(r1.amount) >= 0.01
  RETURN v.address AS address, sum(toFloat(r1.amount)) AS contrib
}
UNION ALL
// Indirect contributions via one intermediary
CALL {
  MATCH (s:Address {address: '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'})- [r2:TRANSFER]->(:Address)-[r3:TRANSFER]->(v:Address)
  WHERE r2.asset = 'ETH' AND r3.asset = 'ETH' AND toFloat(r2.amount) >= 0.01 AND toFloat(r3.amount) >= 0.01
  RETURN v.address AS address, sum(toFloat(r3.amount)) AS contrib
}
WITH address, sum(contrib) AS tainted_in
// Compute total incoming per address
MATCH (:Address)-[t:TRANSFER]->(v:Address {address: address})
WHERE t.asset = 'ETH'
WITH v.address AS address, tainted_in, sum(toFloat(t.amount)) AS total_in
WHERE total_in > 0 AND address <> '0x1db92e2eebc8e0c075a02bea49a2935bcd2dfcf4'
RETURN address, tainted_in, (tainted_in / total_in) AS taint_ratio
ORDER BY tainted_in DESC, taint_ratio DESC
LIMIT 150

